import sys
stdin = sys.stdin.readline

def next_array(): return list(map(int, stdin().split()))

def solve():
    h, w, m = next_array()
    color_count = {}
    row_painted = set()
    col_painted = set()
    ops = []
    for i in range(m):
        t, a, x = next_array()
        ops.append((t, a-1, x))

    for t, a, x in ops:
        if t == 1:
            if a not in row_painted:
                row_painted.add(a)
                color_count[x] = color_count.get(x, 0) + w
        elif t == 2:
            if a not in col_painted:
                col_painted.add(a)
                color_count[x] = color_count.get(x, 0) + h

    for color in color_count:
        print(color, color_count[color])

if __name__ == "__main__":
    solve()
